<template>
  <div class="flex flex-col gap-2">
    <p>Please review the canvasser profile before assigning.</p>
    <AppLoader v-if="isLoading" variant="inline" subject="canvasser profile" />
    <AppError
      v-else-if="error"
      title="Failed to load user profile"
      :error="error"
      :action="refetch"
      action-text="Retry"
    />
    <ProfileBioDisplay
      v-else
      :bio="userProfileDetails?.bio ?? null"
      :profile-picture-url="userProfileDetails?.profile_picture_url ?? null"
      :profile-picture-original-url="userProfileDetails?.profile_picture_original_url ?? null"
      :full-name="`${userProfileDetails?.first_name ?? ''} ${userProfileDetails?.last_name ?? ''}`.trim() || null"
      :role="userProfileDetails?.role ?? null"
      :city="userProfileDetails?.city ?? null"
      :state="userProfileDetails?.state ?? null"
      :joined-at="userProfileDetails?.created_at ?? null"
      empty-message="Canvasser did not provide profile information yet"
    />
  </div>
</template>

<script setup lang="ts">
import { useProfileDetails } from '~/queries/users/profile';

interface Props {
  userId: string;
}

const props = defineProps<Props>();

const { profileDetails: userProfileDetails, isLoading, error, refetch } = useProfileDetails(() => props.userId);
</script>
