import * as z from 'zod';
import type { AssignmentType, ProjectType } from '~/client';
import { numericString, positionSchema } from './utils';

export type AssignmentInfoFormMode = 'create' | 'edit';

export function buildAssignmentInfoSchema(opts: {
  projectType: ProjectType;
  paymentEnabled: boolean;
  increasedPayRateEnabled: boolean;
  /** Regular canvassers only — drives pay rate and assignment type. */
  payRateApplicable: boolean;
  /** Canvasser-like only (canvasser + subcontractor canvasser). */
  canvassingAppUsernameApplicable: boolean;
  mode: AssignmentInfoFormMode;
}) {
  const coerceNullToEmpty = (v: unknown) => (v === null ? '' : v);

  // Used wherever a numeric field is not required (no pay rate, or increased rate disabled):
  // empty string / null / missing all collapse to null, anything else is coerced to a number.
  const optionalNullableNumber = z.preprocess((v) => {
    if (v === '' || v == null) return null;
    const n = Number(v);
    return Number.isNaN(n) ? v : n;
  }, z.number().nullable().optional());

  // When a field does not apply to this assignment (subcontractor canvassers have no
  // pay rate / increased rate / assignment type), force it to null regardless of any
  // stale value the form may still hold — don't rely on the submit-side guards alone.
  const forcedNull = z.preprocess(() => null, z.null());

  const rateSchema = !opts.payRateApplicable
    ? forcedNull
    : z.preprocess(
        coerceNullToEmpty,
        opts.paymentEnabled
          ? numericString('Pay rate', {
              required: true,
              positive: true,
              max: 200,
              messages: { max: 'Pay rate must not exceed $200' },
            })
          : numericString('Pay rate', {
              required: true,
              min: 0,
              max: 200,
              messages: { max: 'Pay rate must not exceed $200' },
            })
      );

  const increasedRateSchema = !opts.payRateApplicable
    ? forcedNull
    : opts.projectType === 'canvassing' && opts.increasedPayRateEnabled
      ? z.preprocess(
          coerceNullToEmpty,
          numericString('Increased pay rate', {
            required: true,
            min: 0,
            max: 300,
            messages: { max: 'Increased pay rate must not exceed $300' },
          })
        )
      : optionalNullableNumber;

  // Optional for everyone (develop: the app username is tracked as a project onboarding checkmark
  // now, so an assignment can be created before it exists). Still pinned to null for roles that
  // cannot hold one — a manager / admin link rejects a non-null username server-side, so letting a
  // stale value through would turn into a 400 rather than a form error.
  const canvasserInAppSchema = !opts.canvassingAppUsernameApplicable ? forcedNull : z.string().nullable().optional();

  const assignmentTypeSchema = opts.payRateApplicable
    ? z
        .string()
        .nonempty('Assignment type is required')
        .transform((v) => v as AssignmentType)
    : forcedNull;

  return z
    .object({
      assignment_type: assignmentTypeSchema,
      rate: rateSchema,
      increased_price_per_hour: increasedRateSchema,
      canvasser_in_app: canvasserInAppSchema,
      position: positionSchema,
    })
    .superRefine((data, ctx) => {
      if (!opts.payRateApplicable || opts.projectType !== 'canvassing' || !opts.increasedPayRateEnabled) return;
      if (typeof data.increased_price_per_hour !== 'number' || typeof data.rate !== 'number') return;
      if (data.increased_price_per_hour < data.rate) {
        ctx.addIssue({
          code: 'custom',
          path: ['increased_price_per_hour'],
          message: 'Increased pay rate must be greater than or equal to the regular pay rate',
        });
      }
    });
}

export type AssignmentInfoSchema = ReturnType<typeof buildAssignmentInfoSchema>;
export type AssignmentInfoFormInput = z.input<AssignmentInfoSchema>;
export type AssignmentInfoFormOutput = z.output<AssignmentInfoSchema>;
