<template>
  <div class="flex flex-col gap-4 h-full break-words">
    <p v-if="mode === 'create'">
      Do you really want to assign
      <span class="font-bold">{{ userFullName }}</span> to the project
      <span class="font-bold">{{ projectName }} ({{ projectType }})</span> as {{ roleLabel }}?
    </p>
    <p v-if="isRegularCanvasser">
      Payments <b>{{ payment.payments_enabled ? 'enabled' : 'disabled' }}</b> for <b>{{ projectName }}</b> project.
    </p>

    <Alert v-if="isRegularCanvasser && mode === 'edit' && projectType === 'canvassing'" variant="info">
      <InfoIcon />
      <AlertDescription>
        Increased pay rate is <b>{{ existingIncreasedPayRateLabel }}</b> for this assignment, and
        <b>{{ projectIncreasedPayRateEnabledLabel }}</b> for the project.
      </AlertDescription>
    </Alert>
    <Alert v-else-if="isRegularCanvasser && mode === 'create' && projectType === 'canvassing'" variant="info">
      <InfoIcon />
      <AlertDescription>
        Increased pay rate is <b>{{ projectIncreasedPayRateEnabledLabel }}</b> for the project, and will be
        <b>{{ projectIncreasedPayRateEnabledLabel }}</b> for this assignment.
      </AlertDescription>
    </Alert>

    <!-- Position applies to every role, so it sits outside the canvasser-only field group below. -->
    <FormItemWrapper label="Position" name="position">
      <template #default="{ slots }">
        <div class="flex flex-col gap-1.5">
          <Input
            id="position"
            type="text"
            maxlength="64"
            placeholder="Position on the customer-facing dashboard"
            data-testid="assignment-position-input"
            v-bind="slots.componentField"
          />
          <p class="text-sm text-muted-foreground">
            Optional. Members with a position appear on this project's public Team tab.
          </p>
        </div>
      </template>
    </FormItemWrapper>

    <div
      v-if="isRegularCanvasser || (projectType === 'canvassing' && isCanvasserLike)"
      class="grid grid-cols-1 md:grid-cols-2 gap-4"
    >
      <template v-if="isRegularCanvasser">
        <FormItemWrapper label="Assignment Type" name="assignment_type">
          <template #default="{ slots }">
            <KitFormsSelect
              id="assignment_type"
              placeholder="Select canvasser assignment type"
              :items="assignmentTypeSelectItems"
              :component-field="slots.componentField"
            />
          </template>
        </FormItemWrapper>

        <FormItemWrapper :label="`Pay rate ${rateLabel}`" name="rate">
          <template #default="{ slots }">
            <div class="relative text-black w-full sm:w-auto">
              <MoneyInput id="rate" class="pl-6 text-md" placeholder="Enter amount" v-bind="slots.componentField" />
              <span class="absolute start-0 inset-y-0 flex items-center justify-center px-1">
                <DollarSign class="size-5" />
              </span>
            </div>
          </template>
        </FormItemWrapper>

        <FormItemWrapper
          v-if="projectType === 'canvassing' && isIncreasedPayRateEnabled"
          label="Increased pay rate (per hour)"
          name="increased_price_per_hour"
        >
          <template #default="{ slots }">
            <div class="relative text-black w-full sm:w-auto">
              <MoneyInput id="increased_price_per_hour" class="pl-6 text-md" v-bind="slots.componentField" />
              <span class="absolute start-0 inset-y-0 flex items-center justify-center px-1">
                <DollarSign class="size-5" />
              </span>
            </div>
          </template>
        </FormItemWrapper>
      </template>

      <FormItemWrapper
        v-if="projectType === 'canvassing' && isCanvasserLike"
        label="Canvassing app username"
        name="canvasser_in_app"
      >
        <template #default="{ slots }">
          <div class="flex flex-col gap-1.5">
            <KitFormsSelect
              id="canvasser_in_app"
              :items="processedCanvassersList"
              placeholder="Select canvasser in project app"
              :component-field="slots.componentField"
              :loading="isLoading"
            />
            <CanvassingAppCanvasserCreateDialog :project-id="projectId" @created="onCanvasserCreated">
              <Button
                type="button"
                variant="link"
                class="h-auto gap-1 self-start p-0"
                data-testid="assignment-add-canvasser-button"
              >
                <Plus />
                Add New Entry
              </Button>
            </CanvassingAppCanvasserCreateDialog>
          </div>
        </template>
      </FormItemWrapper>
    </div>

    <ProfileInfo v-if="isCanvasserLike" :user-id="userId" />
  </div>
</template>

<script setup lang="ts">
// Must be rendered inside a parent that calls useForm() with buildAssignmentInfoSchema().
import { DollarSign, InfoIcon, Plus } from 'lucide-vue-next';
import { useFormContext } from 'vee-validate';
import { getCanvassingAppCanvassersList } from '~/client';
import type { AppCanvasserSelectorListItem, ProjectType, UserRole } from '~/client';
import type { AssignmentPayment } from '~/composables/useCanvasserAssignmentForm';
import { getUserRole } from '~/constants/users/userRoles';
import { canvasserName } from '~/utils/canvassing/format';
import { assignmentTypeSelectItems } from '~/constants/assignments/assignmentTypes';
import {
  type AssignmentInfoFormInput,
  type AssignmentInfoFormOutput,
} from '~/constants/validationSchemas/assignmentInfo';

const props = defineProps<{
  mode: 'create' | 'edit';
  userId: string;
  userRole: UserRole;
  userFullName: string;
  projectId: string;
  projectName: string;
  projectType: ProjectType;
  payment: AssignmentPayment;
  existingIncreasedPayRate?: number | null;
}>();

const { values, setFieldValue } = useFormContext<AssignmentInfoFormInput, AssignmentInfoFormOutput>();

const { isCanvasser } = useUserRole();

// `userRole` here is the TARGET user's role. Regular canvassers get the pay/type
// fields; both canvassers and subcontractor canvassers ("canvasser-like") get the
// canvassing-app username (canvassing projects) and the profile review.
const isRegularCanvasser = computed(() => props.userRole === 'canvasser');
const isCanvasserLike = computed(() => props.userRole === 'canvasser' || props.userRole === 'subcontractor_canvasser');
const roleLabel = computed(() => getUserRole(props.userRole).name);

const { data: canvassers, isLoading } = useQuery({
  key: () => ['selector-canvasser-list', props.projectId],
  query: () =>
    getCanvassingAppCanvassersList({
      composable: '$fetch',
      query: { project_id: props.projectId },
    }),
  enabled: () => !isCanvasser.value && !!props.projectId && props.projectType === 'canvassing',
  staleTime: 0,
});

const processedCanvassersList = computed<SelectItem<string>[]>(() => [
  { name: 'Unassigned', value: null },
  ...(canvassers.value?.items ?? []).map((c) => ({
    name: `${canvasserName(c.first_name, c.last_name) || 'Unknown'} (${c.email})`,
    value: c.email,
  })),
]);

function onCanvasserCreated(item: AppCanvasserSelectorListItem) {
  setFieldValue('canvasser_in_app', item.email);
}

const rateLabel = computed(() => (props.projectType === 'canvassing' ? '(per hour)' : '(per signature)'));

const isIncreasedPayRateEnabled = computed(() =>
  isIncreasedPayRateApplicable(props.payment, props.existingIncreasedPayRate)
);

const projectIncreasedPayRateEnabled = computed(() => isIncreasedPayRateApplicable(props.payment));

const projectIncreasedPayRateEnabledLabel = computed(() =>
  projectIncreasedPayRateEnabled.value ? 'enabled' : 'disabled'
);

const existingIncreasedPayRateLabel = computed(() => (props.existingIncreasedPayRate != null ? 'enabled' : 'disabled'));

// Pay-rate auto-fill. Intentionally a no-op for subcontractor canvassers: their
// dialogs never seed `assignment_type`, so `newType` is falsy and we bail early.
watch(
  [() => values.assignment_type, () => props.payment],
  ([newType]) => {
    if (!newType) return;

    let newRate: number | null | undefined;
    let newIncreasedRate: number | null | undefined;

    if (newType === 'local') {
      newRate = isSignaturePayment(props.payment)
        ? props.payment.for_canvasser_per_signature
        : props.payment.for_canvasser_per_hour;
      if (!isSignaturePayment(props.payment)) newIncreasedRate = props.payment.increased_for_canvasser_per_hour;
    } else if (newType === 'quick_response_force') {
      newRate = isSignaturePayment(props.payment)
        ? props.payment.qrf_for_canvasser_per_signature
        : props.payment.qrf_for_canvasser_per_hour;
      if (!isSignaturePayment(props.payment)) newIncreasedRate = props.payment.increased_qrf_for_canvasser_per_hour;
    }

    if (!(props.mode === 'edit' && values.rate)) {
      setFieldValue('rate', newRate != null ? String(newRate) : null, false);
    }

    if (
      props.projectType === 'canvassing' &&
      isIncreasedPayRateEnabled.value &&
      !(props.mode === 'edit' && values.increased_price_per_hour)
    ) {
      setFieldValue('increased_price_per_hour', newIncreasedRate != null ? String(newIncreasedRate) : null, false);
    }
  },
  { immediate: true }
);
</script>
